sysauto_script.script:
// DedupeGuard — scheduled daily scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runDailyScan() {
    var engine = new DedupeGuardEngine();
    var result = engine.scanAll();

    var tables = result.tables || [];
    var detail = [];
    for (var i = 0; i < tables.length; i++) {
        detail.push(tables[i].table + '=' + tables[i].candidates);
    }

    gs.info('x_snc_ddg daily scan complete: ' +
        result.total_candidates + ' candidates across ' +
        tables.length + ' tables [' + detail.join(', ') + ']');
})();
